fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    assert_eq!(
        x1.len(),
        x2.len(),
        "Input vectors must have the same length"
    );
    x1.iter()
      .zip(x2.iter())
      .map(|(&a, &b)| a & b)
      .collect()
}

